// Raw input from ManyChat
const raw = $json.travel_budget || $json.budget || "";

// Normalize string
let value = raw
  .toString()
  .toLowerCase()
  .replace(/₹|rs\.?|inr|,/g, "")
  .trim();

let number = 0;

// Handle Lakhs (L)
if (value.includes('l')) {
  number = parseFloat(value.replace('l', '')) * 100000;
}

// Handle Thousands (K)
else if (value.includes('k')) {
  number = parseFloat(value.replace('k', '')) * 1000;
}

// Handle plain numbers
else {
  number = parseFloat(value);
}

// Safety fallback
number = isNaN(number) ? 0 : Math.round(number);

// Store clean number
return [{
  json: {
    ...$json,
    travel_budget: number
  }
}];

