// Raw input from ManyChat
const raw = $('Webhook1').first().json.body.budget || "";

// Normalize string: lowercase, remove symbols/commas/spaces
let value = raw
  .toString()
  .toLowerCase()
  .replace(/₹|rs\.?|inr|,/g, "")
  .trim();

let number = 0;

// Handle Lakhs (L)
if (value.includes('l')) {
  number = parseFloat(value.replace(/l/i, '')) * 100000;
}

// Handle Thousands (K)
else if (value.includes('k')) {
  number = parseFloat(value.replace(/k/i, '')) * 1000;
}

// Handle plain numbers
else {
  number = parseFloat(value);

  // If number < 100, assume they meant thousands
  if (number < 100) {
    number = number * 1000;
  }
}

// Safety fallback
number = isNaN(number) ? 0 : Math.round(number);

// Output only travel_budget
return [{
  json: {
    travel_budget: number
  }
}];

